import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    m = (n + 1) // 2
    a = []
    for _ in range(m):
        a.append(int(next(iterator)))

    x = int(next(iterator))

    full_a = a + [x] * (n - m)

    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + full_a[i]

    for k in range(1, n + 1):
        valid = True
        for i in range(n - k + 1):
            s = prefix[i+k] - prefix[i]
            if s <= 0:
                valid = False
                break
        if valid:
            print(k)
            return

    print(-1)

if __name__ == "__main__":
    main()
